`, "",{"version":3,"sources":["webpack://./src/一脸嫌弃给你看胖次的onion/状态栏/components/IfLinePanel.vue"],"names":[],"mappings":"AAmEA,qCACE,iBAAkB,CAClB,iBAAkB,CAClB,mCAAsC,CACtC,+BACF,CAEA,sCACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,kBACF,CAEA,mCACE,cAAe,CACf,eAAgB,CAChB,iBAAkB,CAClB,8BAAkC,CAClC,yBAA6B,CAC7B,eAAgB,CAChB,aACF,CAEA,qCACE,cAAe,CACf,uBAA0B,CAC1B,iBACF,CAEA,uCACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,cAAe,CACf,sBAAuB,CACvB,uBAA0B,CAC1B,cACF,CAEA,uCACE,UAAW,CACX,WAAY,CACZ,oCAAwC,CACxC,oCAAwC,CACxC,iBAAkB,CAClB,kDACF,CAEA,+BACE,GACE,wBACF,CACF,CAEA,uCACE,gBAAiB,CACjB,eAAgB,CAChB,oBACF,CAEA,0DACE,OACF,CAEA,oCACE,cAAe,CACf,eAAgB,CAChB,2BAA+B,CAC/B,QAAS,CACT,oBACF,CAEA,qCACE,aAAc,CACd,uBAA0B,CAC1B,cAAe,CACf,iBACF,CAEA,qCACE,cAAe,CACf,iBACF,CAEA,uCACE,QAAS,CACT,cAAe,CACf,4BAAgC,CAChC,iBACF","sourcesContent":["<template>\n  <div class=\"onion-ifline-panel\">\n    <!-- 标题 -->\n    <div class=\"onion-ifline-header\">\n      <span class=\"onion-ifline-tag\">IF线</span>\n      <span v-if=\"result\" class=\"onion-ifline-title\">{{ result.title }}</span>\n    </div>\n\n    <!-- 加载中 -->\n    <div v-if=\"state === 'generating'\" class=\"onion-ifline-loading\">\n      <div class=\"onion-ifline-spinner\"></div>\n      <span>平行世界线展开中...</span>\n    </div>\n\n    <!-- 内容 -->\n    <div v-else-if=\"state === 'done' && result\" class=\"onion-ifline-content\">\n      <p class=\"onion-ifline-text\">{{ displayText }}</p>\n    </div>\n\n    <!-- 错误 -->\n    <div v-else-if=\"state === 'error'\" class=\"onion-ifline-error\">\n      <span>生成失败，请重试</span>\n    </div>\n\n    <!-- 空状态 -->\n    <div v-else class=\"onion-ifline-empty\">\n      <p>点击下方按钮，窥探另一条世界线</p>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from 'vue';\nimport type { IfLineResult, IfLineState } from '../ifline/types';\n\nconst props = defineProps<{\n  state: IfLineState;\n  result: IfLineResult | null;\n}>();\n\n// 打字机效果\nconst displayText = ref('');\nlet typewriterTimer: ReturnType<typeof setInterval> | null = null;\n\nwatch(\n  () => props.result,\n  (newResult) => {\n    if (!newResult) return;\n    if (typewriterTimer) clearInterval(typewriterTimer);\n\n    displayText.value = '';\n    let idx = 0;\n    const text = newResult.content;\n\n    typewriterTimer = setInterval(() => {\n      if (idx < text.length) {\n        displayText.value += text[idx];\n        idx++;\n      } else if (typewriterTimer) {\n        clearInterval(typewriterTimer);\n      }\n    }, 30);\n  },\n);\n</script>\n\n<style scoped>\n.onion-ifline-panel {\n  padding: 12px 14px;\n  border-radius: 8px;\n  border: 1px solid rgba(255, 200, 0.12);\n  background: rgba(255, 200, 0, 0.04);\n}\n\n.onion-ifline-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 10px;\n}\n\n.onion-ifline-tag {\n  font-size: 10px;\n  padding: 2px 6px;\n  border-radius: 4px;\n  background: rgba(255, 150, 0, 0.2);\n  color: rgba(255, 180, 0, 0.9);\n  font-weight: 600;\n  flex-shrink: 0;\n}\n\n.onion-ifline-title {\n  font-size: 13px;\n  color: rgba(255, 255, 0.7);\n  font-style: italic;\n}\n\n.onion-ifline-loading {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 16px 0;\n  justify-content: center;\n  color: rgba(255, 255, 0.5);\n  font-size: 13px;\n}\n\n.onion-ifline-spinner {\n  width: 14px;\n  height: 14px;\n  border: 2px solid rgba(255, 150, 0, 0.3);\n  border-top-color: rgba(255, 150, 0, 0.8);\n  border-radius: 50%;\n  animation: onion-spin 0.8s linear infinite;\n}\n\n@keyframes onion-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n.onion-ifline-content {\n  max-height: 200px;\n  overflow-y: auto;\n  scrollbar-width: none;\n}\n\n.onion-ifline-content::-webkit-scrollbar {\n  width: 0;\n}\n\n.onion-ifline-text {\n  font-size: 14px;\n  line-height: 1.8;\n  color: rgba(255, 255, 255, 0.8);\n  margin: 0;\n  white-space: pre-wrap;\n}\n\n.onion-ifline-error {\n  padding: 8px 0;\n  color: rgba(255, 100, 0.8);\n  font-size: 12px;\n  text-align: center;\n}\n\n.onion-ifline-empty {\n  padding: 12px 0;\n  text-align: center;\n}\n\n.onion-ifline-empty p {\n  margin: 0;\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.35);\n  font-style: italic;\n}\n</style>\n"],"sourceRoot":""}]);
